import{_ as t,o as r,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2017-MAR-08 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAR-08 :: Ceph Performance Weekly","date":"2017-03-15T00:00:00.000Z","updated":"2017-03-15T00:00:00.000Z","tags":["Ceph","性能优化","BlueStore","存储系统","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),n={name:"posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.md"};function l(g,o,a,i,p,_){return r(),e("div",null,[...o[0]||(o[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： 所有Ceph研发人员</p><p><strong>会议主题</strong>： Ceph存储系统性能优化与改进</p><p><strong>会议内容</strong>：</p><p><strong>一、蓝店（BlueStore）性能优化</strong></p><ol><li><strong>RocksDB范围删除操作优化</strong>： 讨论使用RocksDB范围删除操作以提升蓝店性能，尽管存在性能下降的风险，但仍计划实施，并可能添加配置选项以控制是否使用该操作。</li><li><strong>位图内存使用优化</strong>： 讨论优化位图内存使用，以减少内存消耗并提高性能，计划将位图区域直接嵌入到RaceGo中，以提高CPU缓存效率。</li><li><strong>蓝店启动优化</strong>： 讨论优化蓝店启动速度，减少初始化时间，计划通过优化初始化过程和批处理延迟写入操作来实现。</li><li><strong>延迟写入操作优化</strong>： 讨论优化延迟写入操作，以提高性能，计划在重写延迟写入代码时实现灵活的批处理策略。</li></ol><p><strong>二、其他性能优化</strong></p><ol><li><strong>CRC32优化</strong>： 讨论优化CRC32计算，提高性能，计划使用Intel指令集，以提高计算速度。</li><li><strong>内存使用优化</strong>： 讨论优化内存使用，减少内存消耗，计划在BlueStore中使用连续内存区域，以减少内存碎片。</li><li><strong>对象存储性能优化</strong>： 讨论优化对象存储性能，减少L3缓存缺失，计划使用缓存和优化编译器内联，以提高性能。</li></ol><p><strong>三、其他议题</strong></p><ol><li><strong>RocksDB缓存失效问题</strong>： 研究RocksDB缓存失效导致的随机读取问题，并寻求解决方案。</li><li><strong>对象存储分层存储</strong>： 与UC Santa Cruz研究人员合作，探索对象存储分层存储技术，以提高性能。</li><li><strong>OSD分布优化</strong>： 研究OSD分布优化，以实现更均匀的数据分布。</li></ol><p><strong>四、行动计划</strong></p><ol><li><strong>蓝店性能优化</strong>： 完成蓝店性能优化工作，包括RocksDB范围删除操作优化、位图内存使用优化、蓝店启动优化和延迟写入操作优化。</li><li><strong>其他性能优化</strong>： 完成其他性能优化工作，包括CRC32优化、内存使用优化和对象存储性能优化。</li><li><strong>RocksDB缓存失效问题</strong>： 研究RocksDB缓存失效问题，并寻求解决方案。</li><li><strong>对象存储分层存储</strong>： 与UC Santa Cruz研究人员合作，探索对象存储分层存储技术。</li><li><strong>OSD分布优化</strong>： 研究OSD分布优化，并制定实施计划。</li></ol><p><strong>五、后续会议</strong></p><p>下次会议将讨论蓝店性能优化工作的进展以及其他性能优化议题。</p>',15)])])}const d=t(n,[["render",l]]);export{C as __pageData,d as default};
